/* MediaWiki:Citizen.css  -  the look of aa-classic.com: warm dark brown + orange (dark theme) and warm cream + orange (light theme).
   Colours: header #221f1d, panels #2e2a26 (sampled from screenshots of aa-classic.com), orange #e28552.
   Every colour is a variable at the top (--aa-...), one set for the light theme and one for the dark theme: change them there. */

@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;700&display=swap');

/* ---- LIGHT theme (also what the wiki uses when the browser asks for light) ---- */
:root,
.skin-theme-clientpref-day {
  --color-progressive-oklch__h: 45;       /* the orange accent for links and buttons */
  --color-surface-0: #f6f1e7;             /* the page background: warm cream */
  --color-surface-1: #fbf7ef;
  --color-surface-2: #efe7d8;
  --color-surface-3: #e4dac6;
  --color-surface-4: #d8ccb4;
  --color-base: #3a2f26;                  /* the text: dark brown */

  --aa-card: #fffaf0;                     /* cards, tiles and lists on the Main Page */
  --aa-edge: #ddd1ba;
  --aa-edge-hover: #b9a888;
  --aa-title: #2f2620;
  --aa-text: #3a2f26;
  --aa-muted: #7a6e5e;
  --aa-accent: #c4622d;
  --aa-bullet: #b9a888;
  --aa-header-bg: #efe7d8;                /* the top bar */
  --aa-header-line: #d9cdb5;
  --aa-search-bg: #fbf7ef;
  --aa-search-line: #d9cdb5;
  --aa-bg-overlay: rgba(246, 241, 231, .90);   /* the veil over the background art: higher last number = calmer art */
  --aa-panel: rgba(255, 250, 240, .94);          /* the panel behind the wiki content */
  --aa-outline: #b9a888;                          /* the line around that panel */
  --aa-outline-glow: rgba(185, 168, 136, .25);    /* the soft second line outside it */
}

/* ---- DARK theme ---- */
.skin-theme-clientpref-night {
  --color-progressive-oklch__h: 50;
  --color-surface-0: #1d1916;
  --color-surface-1: #2a2623;
  --color-surface-2: #2e2a26;
  --color-surface-3: #38322d;
  --color-surface-4: #433c36;
  --color-base: #dedede;

  --aa-card: #2e2a26;
  --aa-edge: #3d3732;
  --aa-edge-hover: #6a5d48;
  --aa-title: #ece7dc;
  --aa-text: #dedede;
  --aa-muted: #8a8478;
  --aa-accent: #e28552;
  --aa-bullet: #6a5d48;
  --aa-header-bg: #221f1d;
  --aa-header-line: #332d2a;
  --aa-search-bg: #1d1916;
  --aa-search-line: #3a3430;
  --aa-bg-overlay: rgba(29, 25, 22, .62);
  --aa-panel: rgba(38, 33, 30, .94);
  --aa-outline: #6a5d48;
  --aa-outline-glow: rgba(226, 133, 82, .14);
}
/* the same when the wiki follows the browser's setting ("Auto") and the browser asks for dark */
@media (prefers-color-scheme: dark) {
  .skin-theme-clientpref-os {
    --color-progressive-oklch__h: 50;
    --color-surface-0: #1d1916;
    --color-surface-1: #2a2623;
    --color-surface-2: #2e2a26;
    --color-surface-3: #38322d;
    --color-surface-4: #433c36;
    --color-base: #dedede;

    --aa-card: #2e2a26;
    --aa-edge: #3d3732;
    --aa-edge-hover: #6a5d48;
    --aa-title: #ece7dc;
    --aa-text: #dedede;
    --aa-muted: #8a8478;
    --aa-accent: #e28552;
    --aa-bullet: #6a5d48;
    --aa-header-bg: #221f1d;
    --aa-header-line: #332d2a;
    --aa-search-bg: #1d1916;
    --aa-search-line: #3a3430;
    --aa-bg-overlay: rgba(29, 25, 22, .62);
    --aa-panel: rgba(38, 33, 30, .94);
    --aa-outline: #6a5d48;
    --aa-outline-glow: rgba(226, 133, 82, .14);
  }
}

/* ---- the colours of the Main Page (its sizes and layout are in Template:MainPage/styles.css) ---- */
html .aa-mp { color: var(--aa-text); }
html .aa-mp .aa-mp-card,
html .aa-mp .aa-mp-tile,
html .aa-mp .aa-mp-list { background: var(--aa-card); border-color: var(--aa-edge); }
html .aa-mp .aa-mp-card:hover,
html .aa-mp .aa-mp-tile:hover { border-color: var(--aa-edge-hover); }
html .aa-mp .aa-mp-eyebrow { color: var(--aa-accent); }
html .aa-mp .aa-mp-h,
html .aa-mp .aa-mp-cardtitle,
html .aa-mp .aa-mp-sub,
html .aa-mp .aa-mp-listtitle { color: var(--aa-title); }
html .aa-mp .aa-mp-cardsub { color: var(--aa-muted); }
html .aa-mp .aa-mp-tile a { color: var(--aa-title); }
html .aa-mp .aa-mp-list li::before { background: var(--aa-bullet); }

/* ---- the background art: a painting behind the whole wiki that shows on the sides of wide screens ----
   Upload the picture as "File:Naval.webp" (Special:Upload). Without it the page is simply the plain colour.
   If the live wiki serves pages from /w/ (e.g. /w/index.php), change the path to /w/index.php?title=Special:FilePath/Naval.webp */
body { background-color: var(--color-surface-0); }
/* the painting is split in two: its left part sits on the left side of the window and its right part on the right side.
   Each half is shown at the natural proportions (fitted to the window height, never zoomed in) and fades out towards
   the middle, where the content panel covers it anyway. */
body::before,
body::after {
  content: "";
  position: fixed;
  top: 0;
  bottom: 0;
  width: 50vw;
  z-index: -1;
  pointer-events: none;
  background-repeat: no-repeat;
  background-size: auto, auto 100%;
}
body::before {
  left: 0;
  background-image: linear-gradient(var(--aa-bg-overlay), var(--aa-bg-overlay)), url(/Special:FilePath/Naval.webp);
  background-position: 0 0, left center;
  -webkit-mask-image: linear-gradient(to right, #000 0, #000 50%, transparent 100%);
  mask-image: linear-gradient(to right, #000 0, #000 50%, transparent 100%);
}
body::after {
  right: 0;
  background-image: linear-gradient(var(--aa-bg-overlay), var(--aa-bg-overlay)), url(/Special:FilePath/Naval.webp);
  background-position: 0 0, right center;
  -webkit-mask-image: linear-gradient(to left, #000 0, #000 50%, transparent 100%);
  mask-image: linear-gradient(to left, #000 0, #000 50%, transparent 100%);
}
.citizen-page-container { background: transparent; }
/* the main block that holds the wiki content: a panel with an outline, so it stands out from the art behind it */
@media (min-width: 1000px) {
  .mw-body-content {
    background: var(--aa-panel);
    border: 1px solid var(--aa-outline);
    border-radius: 8px;
    padding: 24px 28px;
    box-shadow: 0 0 0 4px var(--aa-outline-glow), 0 12px 40px rgba(0, 0, 0, .35);
  }
  .citizen-page-container { padding-left: 0; }       /* the old left strip is gone, so no empty space for it */
}

/* serif titles like the main site */
#firstHeading,
.mw-body-content h1,
.mw-body-content h2,
.mw-body-content h3 {
  font-family: 'Cormorant Garamond', Georgia, 'Times New Roman', serif;
  font-weight: 700;
}

/* ---- the header: a top bar like aa-classic.com instead of Citizen's left icon strip (wide screens only) ---- */
@media (min-width: 1000px) {
  .citizen-header {
    top: 0;
    left: 0;
    right: 0;
    bottom: auto;
    width: auto;
    height: 64px;
    flex-direction: row;
    align-items: center;
    padding: 0 16px;
    gap: 4px;
    background: var(--aa-header-bg) !important;
    border-bottom: 1px solid var(--aa-header-line);
  }
  /* the drop-down boxes (menu, preferences, user) opened upwards in Citizen's bottom bar: open them downwards */
  .citizen-header .citizen-menu__card {
    top: calc(100% + 8px);
    bottom: auto;
  }
  /* the menu box: on wide windows Citizen put it to the right of the old left strip, which is off the screen now */
  html body .citizen-header .citizen-drawer .citizen-drawer__card {
    left: 0;
    right: auto;
    top: calc(100% + 8px);
    bottom: auto;
  }
  /* the boxes on the right (preferences, user) open under their buttons, kept inside the window */
  html body .citizen-header .citizen-header__end .citizen-dropdown .citizen-menu__card {
    left: auto;
    right: 8px;
    top: calc(100% + 8px);
    bottom: auto;
  }
  /* the page starts under the bar instead of behind it */
  .citizen-page-container { padding-top: 64px; }
  .citizen-drawer { order: 0; }                       /* the menu button on the left */
  .citizen-header__logo { order: 1; display: flex; align-items: center; border-bottom: 0; height: auto; }
  .citizen-header__logo::after {                      /* the name next to the logo: change the text here */
    content: "AAClassic Wiki";
    margin-left: 8px;
    font-family: 'Cormorant Garamond', Georgia, 'Times New Roman', serif;
    font-weight: 700;
    font-size: 22px;
    letter-spacing: .03em;
    color: var(--aa-title);
  }
  .citizen-search { order: 2; margin-left: auto; width: auto; height: auto; }
  .citizen-header__inner { order: 3; flex-direction: row; height: auto; flex: none; }
  .citizen-header__end { flex-direction: row; }
  /* the search button becomes a search field look */
  #citizen-search-summary {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: flex-start;
    gap: 8px;
    width: 260px;
    height: 36px;
    padding: 0 12px;
    border: 1px solid var(--aa-search-line);
    border-radius: 4px;
    background: var(--aa-search-bg);
    color: var(--aa-muted);
    font-size: 13px;
    font-weight: 400;
  }
  #citizen-search-summary::after { content: "Search the wiki"; }
}

/* ---- closer to aa-classic.com: glass panels, rounder corners, orange glow on hover ---- */
@media (min-width: 1000px) {
  .mw-body-content {
    background: var(--aa-panel);
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
    border-radius: 14px;
    border: 1px solid var(--aa-outline);
    box-shadow: 0 0 0 3px var(--aa-outline-glow), 0 18px 50px rgba(0, 0, 0, .4), inset 0 1px 0 rgba(255, 255, 255, .05);
  }
}
.skin-theme-clientpref-night { --aa-panel: rgba(38, 33, 30, .80); }
@media (prefers-color-scheme: dark) { .skin-theme-clientpref-os { --aa-panel: rgba(38, 33, 30, .80); } }
.skin-theme-clientpref-day { --aa-panel: rgba(255, 250, 240, .86); }

/* header: a soft shadow under the bar, like the site */
.citizen-header { box-shadow: 0 2px 14px rgba(0, 0, 0, .35); }

/* Main Page cards, tiles and lists: rounder, with a faint glass look and an orange glow when hovered */
html .aa-mp .aa-mp-card,
html .aa-mp .aa-mp-tile,
html .aa-mp .aa-mp-list,
html .aa-mp .aa-mp-hero {
  border-radius: 12px;
}
html .aa-mp .aa-mp-card,
html .aa-mp .aa-mp-tile {
  transition: border-color .18s, box-shadow .18s, transform .18s;
}
html .aa-mp .aa-mp-card:hover,
html .aa-mp .aa-mp-tile:hover {
  border-color: var(--aa-accent);
  box-shadow: 0 0 0 1px var(--aa-accent), 0 6px 22px rgba(226, 133, 82, .18);
  transform: translateY(-2px);
}
html .aa-mp .aa-mp-search .citizen-search-trigger { border-radius: 10px; }
html .aa-mp .aa-mp-pico,
html .aa-mp .aa-mp-pic { border-radius: 8px; }
html .aa-mp .aa-mp-card .aa-mp-pic { border-radius: 12px 12px 0 0; }

/* ---- content boxes like the account sidebar on aa-classic.com: one thin soft outline, big round corners, no glow ring ---- */
.skin-theme-clientpref-night { --aa-outline: rgba(226, 133, 82, .22); }
@media (prefers-color-scheme: dark) { .skin-theme-clientpref-os { --aa-outline: rgba(226, 133, 82, .22); } }
.skin-theme-clientpref-day { --aa-outline: rgba(185, 168, 136, .7); }
@media (min-width: 1000px) {
  .mw-body-content {
    border: 1px solid var(--aa-outline);
    border-radius: 18px;
    box-shadow: 0 10px 34px rgba(0, 0, 0, .35);
  }
}
html .aa-mp .aa-mp-card,
html .aa-mp .aa-mp-tile,
html .aa-mp .aa-mp-list,
html .aa-mp .aa-mp-hero { border-radius: 14px; }
html .aa-mp .aa-mp-card .aa-mp-pic { border-radius: 14px 14px 0 0; }

/* ---- darker browns, closer to aa-classic.com (dark theme) ---- */
.skin-theme-clientpref-night {
  --color-surface-0: #14110f;
  --color-surface-1: #1d1917;
  --color-surface-2: #221e1b;
  --color-surface-3: #2b2521;
  --color-surface-4: #342d28;
  --aa-header-bg: #181513;
  --aa-header-line: #2a2420;
  --aa-search-bg: #12100e;
  --aa-card: #23201d;
  --aa-edge: #332d28;
  --aa-panel: rgba(25, 22, 20, .86);
  --aa-bg-overlay: rgba(18, 15, 13, .72);
}
@media (prefers-color-scheme: dark) {
  .skin-theme-clientpref-os {
    --color-surface-0: #14110f;
    --color-surface-1: #1d1917;
    --color-surface-2: #221e1b;
    --color-surface-3: #2b2521;
    --color-surface-4: #342d28;
    --aa-header-bg: #181513;
    --aa-header-line: #2a2420;
    --aa-search-bg: #12100e;
    --aa-card: #23201d;
    --aa-edge: #332d28;
    --aa-panel: rgba(25, 22, 20, .86);
    --aa-bg-overlay: rgba(18, 15, 13, .72);
  }
}

/* the top-left logo: the picture of the uploaded file "File:Favicon.png" */
.citizen-header__logo .mw-logo-icon {
  content: url(/Special:FilePath/Favicon.png);
  object-fit: contain;
}

/* the orange "+" after the name, copied from the aa-classic.com logo (same shape and colour) */
.citizen-header__logo::before {
  content: "";
  order: 3;
  align-self: flex-start;
  width: 13px;
  height: 13px;
  margin: 10px 0 0 2px;
  background: #f2c88f;
  clip-path: polygon(38% 12%, 44% 4%, 56% 4%, 62% 12%, 62% 38%, 88% 38%, 96% 44%, 96% 56%, 88% 62%, 62% 62%, 62% 88%, 56% 96%, 44% 96%, 38% 88%, 38% 62%, 12% 62%, 4% 56%, 4% 44%, 12% 38%, 38% 38%);
}
.citizen-header__logo::after { order: 2; }

/* ---- top-left logo like aa-classic.com: the emblem + CLASSIC wordmark picture, the orange +, and a small WIKI label ----
   Upload Logo.png as "File:Logo.png" (Special:Upload). */
.citizen-header__logo .mw-logo-icon {
  content: url(/Special:FilePath/Logo.png);
  height: 36px;
  width: auto;
  max-width: none;
  object-fit: contain;
}
.citizen-header__logo::before { order: 1; margin: 4px 0 0 3px; }
.citizen-header__logo::after {
  content: "WIKI";
  order: 2;
  align-self: flex-end;
  margin: 0 0 6px 10px;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .3em;
  color: var(--aa-muted);
}

/* the logo button is normally a small square; let it grow to the full width of the logo picture */
.citizen-header__logo,
.citizen-header__logo .mw-logo {
  width: auto !important;
  overflow: visible !important;
}
.citizen-header__logo .mw-logo-icon {
  height: 36px !important;
  width: auto !important;
  max-width: none !important;
  aspect-ratio: auto !important;
}

/* the logo, drawn as a background picture of the link (works whatever the wiki has set as its logo) */
.citizen-header__logo .mw-logo {
  display: block !important;
  width: 131px !important;
  height: 36px !important;
  background: url(/Special:FilePath/Logo.png) no-repeat left center / contain !important;
}
.citizen-header__logo .mw-logo-icon,
.citizen-header__logo .mw-logo .citizen-ui-icon {
  display: none !important;
}

/* ---- exact colours read from aa-classic.com's own stylesheet ----
   page #120e0b, top bar #14100e (95%), panels #211b17, cards #120e0b (94%), text #f7f0e8, accent #e28552,
   lines rgba(226,133,82,.1-.15) and rgba(247,240,233,.1), light "paper" #ece1cc with text #2b1f15 */
.skin-theme-clientpref-night {
  --color-surface-0: #120e0b;
  --color-surface-1: #1b1511;
  --color-surface-2: #211b17;
  --color-surface-3: #2b231d;
  --color-surface-4: #342b24;
  --color-base: #f7f0e8;
  --aa-card: rgba(18, 14, 11, .94);
  --aa-edge: rgba(247, 240, 233, .1);
  --aa-edge-hover: rgba(226, 133, 82, .45);
  --aa-title: #f7f0e8;
  --aa-text: rgba(247, 240, 232, .87);
  --aa-muted: rgba(247, 240, 232, .6);
  --aa-header-bg: rgba(20, 16, 14, .95);
  --aa-header-line: rgba(226, 133, 82, .1);
  --aa-search-bg: rgba(18, 14, 11, .6);
  --aa-search-line: rgba(247, 240, 233, .14);
  --aa-panel: rgba(33, 27, 23, .86);
  --aa-outline: rgba(226, 133, 82, .15);
  --aa-bg-overlay: rgba(18, 14, 11, .7);
}
@media (prefers-color-scheme: dark) {
  .skin-theme-clientpref-os {
    --color-surface-0: #120e0b;
    --color-surface-1: #1b1511;
    --color-surface-2: #211b17;
    --color-surface-3: #2b231d;
    --color-surface-4: #342b24;
    --color-base: #f7f0e8;
    --aa-card: rgba(18, 14, 11, .94);
    --aa-edge: rgba(247, 240, 233, .1);
    --aa-edge-hover: rgba(226, 133, 82, .45);
    --aa-title: #f7f0e8;
    --aa-text: rgba(247, 240, 232, .87);
    --aa-muted: rgba(247, 240, 232, .6);
    --aa-header-bg: rgba(20, 16, 14, .95);
    --aa-header-line: rgba(226, 133, 82, .1);
    --aa-search-bg: rgba(18, 14, 11, .6);
    --aa-search-line: rgba(247, 240, 233, .14);
    --aa-panel: rgba(33, 27, 23, .86);
    --aa-outline: rgba(226, 133, 82, .15);
    --aa-bg-overlay: rgba(18, 14, 11, .7);
  }
}
.skin-theme-clientpref-day {
  --color-surface-0: #ece1cc;
  --color-surface-1: #f3ead9;
  --color-surface-2: #e6dac2;
  --color-base: #2b1f15;
  --aa-title: #2b1f15;
  --aa-text: #2b1f15;
  --aa-header-bg: #e6dac2;
}
/* the top bar blurs what is behind it, like the site */
.citizen-header { -webkit-backdrop-filter: blur(20px); backdrop-filter: blur(20px); }

/* cards a bit lighter than the panel behind them (change the colour here if you want them lighter or darker) */
.skin-theme-clientpref-night { --aa-card: #2b241f; }
@media (prefers-color-scheme: dark) { .skin-theme-clientpref-os { --aa-card: #2b241f; } }

/* the round logo in the menu box (and the footer) was a broken picture: show Favicon.png there instead */
.citizen-drawer__logo {
  background: url(/Special:FilePath/Favicon.png) no-repeat center / contain !important;
}
.citizen-drawer__logo .mw-logo-icon,
.citizen-footer__sitetitle .mw-logo-icon {
  visibility: hidden !important;
}

/* the preferences and user boxes grow out of their top-right corner (under their buttons); the menu box grows from top-left */
html body .citizen-header .citizen-header__end .citizen-dropdown .citizen-menu__card {
  transform-origin: top right !important;
}
html body .citizen-header .citizen-drawer .citizen-drawer__card {
  transform-origin: top left !important;
}

/* top bar contents sit in a centred column like aa-classic.com (logo left, search in the middle, buttons right) */
@media (min-width: 1000px) {
  .citizen-header {
    padding-left: max(16px, calc((100vw - 1340px) / 2)) !important;
    padding-right: max(16px, calc((100vw - 1340px) / 2)) !important;
  }
  .citizen-search {
    margin-left: auto !important;
    margin-right: auto !important;
  }
}

/* the drop-down boxes line up with the right edge of the centred bar (under the buttons), and the menu box with the left edge */
@media (min-width: 1000px) {
  html body .citizen-header .citizen-header__end .citizen-dropdown .citizen-menu__card {
    right: max(8px, calc((100vw - 1340px) / 2 + 8px)) !important;
  }
  html body .citizen-header .citizen-drawer .citizen-drawer__card {
    left: max(8px, calc((100vw - 1340px) / 2 + 8px)) !important;
  }
}

/* when a page starts straight with a heading, don't leave a big empty gap above it inside the panel */
.mw-body-content .mw-parser-output > .mw-heading:first-child,
.mw-body-content .mw-parser-output > h2:first-child,
.mw-body-content .mw-parser-output > h3:first-child {
  margin-top: 0;
  padding-top: 0;
}
.mw-body-content .mw-parser-output > .mw-heading:first-child > h2,
.mw-body-content .mw-parser-output > .mw-heading:first-child > h3 {
  margin-top: 0;
}

/* the first heading of a page that has no intro text (Citizen puts an empty "section 0" in front of it) */
.mw-body-content .mw-parser-output > .citizen-section:first-child + .mw-heading {
  margin-top: 0;
}

/* nudge the menu button and logo to the left, so the menu button lines up with the left edge of the content */
@media (min-width: 1000px) {
  .citizen-header {
    padding-left: max(8px, calc((100vw - 1340px) / 2 - 20px)) !important;
  }
  html body .citizen-header .citizen-drawer .citizen-drawer__card {
    left: max(8px, calc((100vw - 1340px) / 2 - 12px)) !important;
  }
}

/* the search field: exactly in the middle of the page, and wider */
@media (min-width: 1000px) {
  .citizen-header .citizen-search {
    position: absolute !important;
    left: 50% !important;
    top: 50% !important;
    transform: translate(-50%, -50%);
    margin: 0 !important;
  }
  #citizen-search-summary {
    width: 440px !important;
  }
}

/* the search field no longer takes part in the row, so push the buttons to the right edge themselves */
@media (min-width: 1000px) {
  .citizen-header .citizen-header__inner {
    margin-left: auto !important;
  }
}


/* jumping to a section (Contents links, #links): stop just below the fixed top bar.
   Citizen worked out this distance for its old left bar, which put the section far down the screen. */
html {
  scroll-padding-top: 88px !important;
  scroll-padding-bottom: 0 !important;
}

